// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 1 ether);

        vm.prank(alice);
        c.deposit{value: 1}();

        vm.prank(alice);
        c.withdrawAll();
        uint256 balanceAfterFirst = address(alice).balance;

        vm.prank(alice);
        c.withdrawAll();
        uint256 balanceAfterSecond = address(alice).balance;

        assertTrue(balanceAfterSecond == balanceAfterFirst, "Second withdrawal should not increase balance");
    }
}
